export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function zoomAt(s,z,q){z=clamp(z,.7,2.3);return{x:q.x-600-(q.x-600-s.x)*z/s.z,y:q.y-400-(q.y-400-s.y)*z/s.z,z}}
export function createCamera(map,layer,output,onInterrupt){let s={x:0,y:0,z:1},raf=0,done=null,pointers=new Map(),gesture=null,suppress=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');try{const v=JSON.parse(sessionStorage.getItem('world-camera'));if(v&&['x','y','z'].every(k=>Number.isFinite(v[k])))s=v}catch{}
function draw(save=true){s.z=clamp(s.z,.7,2.3);s.x=clamp(s.x,-450,450);s.y=clamp(s.y,-280,280);layer.setAttribute('transform',`translate(${600+s.x} ${400+s.y}) scale(${s.z}) translate(-600 -400)`);output.value=Math.round(s.z*100)+'%';if(save)try{sessionStorage.setItem('world-camera',JSON.stringify(s))}catch{}}
function cancel(){cancelAnimationFrame(raf);raf=0;if(done){done(false);done=null}}
function interrupt(){cancel();onInterrupt?.()}
function move(to,duration=550){cancel();if(reduced.matches||duration===0){s={...to};draw();return Promise.resolve(true)}const from={...s};let start;return new Promise(resolve=>{done=resolve;function tick(t){start??=t;const k=clamp((t-start)/duration,0,1),e=1-(1-k)**3;s={x:from.x+(to.x-from.x)*e,y:from.y+(to.y-from.y)*e,z:from.z+(to.z-from.z)*e};draw(false);if(k<1)raf=requestAnimationFrame(tick);else{raf=0;done=null;draw();resolve(true)}}raf=requestAnimationFrame(tick)})}
const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(map.getScreenCTM().inverse());function baseline(){const a=[...pointers.values()];gesture=a.length>1?{s:{...s},q:{x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2},d:Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)}:a.length?{s:{...s},q:a[0]}:null}
map.addEventListener('pointerdown',e=>{if(e.button!==0)return;interrupt();if(!pointers.size)suppress=false;pointers.set(e.pointerId,point(e));baseline();(e.target.closest(".building")||map).setPointerCapture(e.pointerId)});map.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,point(e));const a=[...pointers.values()];if(a.length>1){suppress=true;const q={x:(a[0].x+a[1].x)/2,y:(a[0].y+a[1].y)/2};s=zoomAt(gesture.s,gesture.s.z*Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)/Math.max(gesture.d,1),gesture.q);s.x+=q.x-gesture.q.x;s.y+=q.y-gesture.q.y}else{const dx=a[0].x-gesture.q.x,dy=a[0].y-gesture.q.y;if(Math.hypot(dx,dy)>6)suppress=true;if(!suppress)return;s={...gesture.s,x:gesture.s.x+dx,y:gesture.s.y+dy}}draw(false)});for(const name of ['pointerup','pointercancel','lostpointercapture'])map.addEventListener(name,e=>{pointers.delete(e.pointerId);baseline();draw()});map.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopImmediatePropagation();suppress=false}},true);map.addEventListener('wheel',e=>{e.preventDefault();interrupt();s=zoomAt(s,s.z*Math.exp(-e.deltaY*.001),point(e));draw()},{passive:false});draw();return{get:()=>({...s}),move,cancel,interrupt,zoom:f=>{interrupt();return move(zoomAt(s,s.z*f,{x:600,y:400}),180)},reset:()=>{interrupt();return move({x:0,y:0,z:1})},restore:v=>{cancel();s={...v};draw()}}}
